// Auto-generated single source of truth for lab architectural guides
export const guides: Record<string, string> = {
	'apis/realtime-webhooks':
		'<h3>Real-Time Streaming & Webhook Signatures</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tChoosing between unidirectional Server-Sent Events (SSE) and bidirectional WebSockets, and\n\t\t\tprotecting webhook endpoints with timing-safe signature verification.\n\t\t</p>\n\t\t<div class="not-prose my-4 overflow-x-auto">\n\t\t\t<table\n\t\t\t\tclass="w-full overflow-hidden rounded-2xl border border-slate-200 text-left font-mono text-sm dark:border-slate-800"\n\t\t\t>\n\t\t\t\t<thead\n\t\t\t\t\tclass="border-b border-slate-200 bg-slate-100 text-slate-700 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-300"\n\t\t\t\t>\n\t\t\t\t\t<tr>\n\t\t\t\t\t\t<th class="p-3 font-bold">Protocol</th>\n\t\t\t\t\t\t<th class="p-3 font-bold">Direction</th>\n\t\t\t\t\t\t<th class="p-3 font-bold">Transport & Overhead</th>\n\t\t\t\t\t\t<th class="p-3 font-bold">Ideal Use Case</th>\n\t\t\t\t\t</tr>\n\t\t\t\t</thead>\n\t\t\t\t<tbody\n\t\t\t\t\tclass="divide-y divide-slate-200 bg-white text-slate-600 dark:divide-slate-800/60 dark:bg-slate-950/40 dark:text-slate-400"\n\t\t\t\t>\n\t\t\t\t\t<tr>\n\t\t\t\t\t\t<td class="p-3 font-bold text-slate-900 dark:text-slate-200">Short Polling</td>\n\t\t\t\t\t\t<td class="p-3 font-bold text-amber-600 dark:text-amber-400">Client → Server</td>\n\t\t\t\t\t\t<td class="p-3">Frequent HTTP GETs; high header overhead</td>\n\t\t\t\t\t\t<td class="p-3">Low-frequency status checks, legacy fallback</td>\n\t\t\t\t\t</tr>\n\t\t\t\t\t<tr>\n\t\t\t\t\t\t<td class="p-3 font-bold text-slate-900 dark:text-slate-200">Long Polling</td>\n\t\t\t\t\t\t<td class="p-3 font-bold text-amber-600 dark:text-amber-400">Server → Client (Held)</td>\n\t\t\t\t\t\t<td class="p-3">Connection held open until event; high server churn</td>\n\t\t\t\t\t\t<td class="p-3">Environments where WebSockets/SSE are blocked by firewalls</td>\n\t\t\t\t\t</tr>\n\t\t\t\t\t<tr>\n\t\t\t\t\t\t<td class="p-3 font-bold text-slate-900 dark:text-slate-200"\n\t\t\t\t\t\t\t>Server-Sent Events (SSE)</td\n\t\t\t\t\t\t>\n\t\t\t\t\t\t<td class="p-3 font-bold text-indigo-600 dark:text-indigo-400">Server → Client</td>\n\t\t\t\t\t\t<td class="p-3">HTTP/2 multiplexed, auto-reconnect, 0 socket overhead</td>\n\t\t\t\t\t\t<td class="p-3">AI LLM token streams, live market tickers, telemetry</td>\n\t\t\t\t\t</tr>\n\t\t\t\t\t<tr>\n\t\t\t\t\t\t<td class="p-3 font-bold text-slate-900 dark:text-slate-200">WebSockets</td>\n\t\t\t\t\t\t<td class="p-3 font-bold text-emerald-600 dark:text-emerald-400">Full Bidirectional</td>\n\t\t\t\t\t\t<td class="p-3">Raw TCP frames (ws:// / wss://), 2–10 byte framing</td>\n\t\t\t\t\t\t<td class="p-3">Multiplayer gaming, collaborative whiteboards, live chat</td>\n\t\t\t\t\t</tr>\n\t\t\t\t</tbody>\n\t\t\t</table>\n\t\t</div>',
	'apis/schema-rpc':
		'<h3>Schema Validation (Standard Schema) & Hono RPC</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tStandard Schema and Hono RPC eliminate boilerplate by providing end-to-end type safety between\n\t\t\tbackend handlers and frontend clients without code-generation steps.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Runtime Boundary Safety:</strong> TypeScript types evaporate at build time. Standard Schema\n\t\t\t\t(Zod / Valibot) validates untrusted JSON at the network perimeter.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>End-to-End Type-Safe RPCs:</strong> Exporting route definitions directly enables auto-completion\n\t\t\t\tand compile-time contract enforcement.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>OpenAPI 3.1 & Scalar:</strong> Generates standardised JSON specs automatically for external\n\t\t\t\tconsumers and automated SDK generation.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Unified Web & Mobile (Android) Backend:</strong> OpenAPI specs allow tools like\n\t\t\t\t<code>openapi-generator</code> to generate type-safe Kotlin models (Retrofit/Ktor) for native\n\t\t\t\tAndroid apps alongside TypeScript web clients from a single backend.\n\t\t\t</li>\n\t\t</ul>',
	'business/monetization':
		'<h3>Site & Project Monetisation Models</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tMonetising developer software tools, SaaS products, and open-source packages requires choosing\n\t\t\tbetween Merchant of Record platforms, direct payment gateways, and usage-based billing.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Merchant of Record (MoR) vs Direct Gateway:</strong> An MoR (such as Polar.sh) acts as\n\t\t\t\tthe legal reseller, assuming all worldwide tax liabilities (EU VAT, US sales tax) so developers\n\t\t\t\tdon\'t have to register across dozens of jurisdictions.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Tiered Pro Paywalls:</strong> Protect premium server endpoints and client features with\n\t\t\t\tcryptographic session entitlements.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Usage Metering:</strong> Bill consumers precisely for compute or API calls using Redis\n\t\t\t\tatomic counters synced to billing webhooks.\n\t\t\t</li>\n\t\t</ul>',
	'business/software-licenses':
		'<h3>Software Licence Types & Open Source Strategy</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tSelecting the right software licence governs intellectual property rights, commercial\n\t\t\texploitation, patent protection, and source code redistribution requirements.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Permissive Licences (MIT, Apache 2.0, BSD):</strong> Maximum freedom with minimal obligations\n\t\t\t\t(keep copyright notice). Apache 2.0 adds explicit patent defence.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Copyleft Licences (MPL, GPL, AGPL):</strong> Ensures software remains open. AGPL-3.0 specifically\n\t\t\t\tcloses the cloud SaaS loophole by triggering disclosure when accessed over a network.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Source-Available Licences (BSL 1.1, FSL):</strong> Not strictly OSI Open Source, but allows\n\t\t\t\tpublic code inspection and non-competing use while converting to permissive open source after\n\t\t\t\ta fixed duration.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Dual-Licensing Model:</strong> Providing software under both a strong copyleft / source-available\n\t\t\t\tlicence (for community) and a commercial proprietary licence (for enterprise customers).\n\t\t\t</li>\n\t\t</ul>',
	'cloud/containers-iac':
		'<h3>Containers, Orchestration & IaC: Podman, Docker, OCI, ECS & Terraform</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tModern cloud applications bridge development and production through OCI container standards\n\t\t\tand declarative Infrastructure as Code (IaC).\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Rootless Podman vs Docker:</strong> Podman runs containers directly under user namespaces\n\t\t\t\twithout a centralised background root daemon, preventing root privilege escalation.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Container as a Service (CaaS):</strong> AWS ECS Fargate and Render allow hosting stateful\n\t\t\t\tNode servers, WebSockets, and background workers without managing underlying virtual machines.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Declarative IaC:</strong> OpenTofu, Terraform, and Pulumi treat cloud topology as version-controlled\n\t\t\t\tsource code, enabling reproducible deployments across multi-region environments.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Open Container Initiative (OCI):</strong> Adheres to strict <code>image-spec</code>\n\t\t\t\tand\n\t\t\t\t<code>runtime-spec</code> definitions supported across all container engines.\n\t\t\t</li>\n\t\t</ul>',
	'cloud/platforms-deployment':
		'<h3>Cloud Platforms: Cloudflare Workers, Vercel & Netlify</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tComparing cloud deployment architectures for Nuxt and SvelteKit applications across V8 Edge\n\t\t\tIsolates and containerised Serverless Functions.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>V8 Isolates vs Containerised Node:</strong> Cloudflare Workers spin up in 0–5ms by sharing\n\t\t\t\ta single V8 runtime process, whereas standard Node lambdas incur container cold starts.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Bandwidth & Egress Optimisation:</strong> Evaluating egress fees and static asset caching\n\t\t\t\tpolicies across platforms.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Reverse & Forward Proxying:</strong> Reverse proxies (Cloudflare, Nginx, Caddy)\n\t\t\t\thandle inbound SSL termination, rate limiting, and <code>X-Forwarded-For</code> header passing\n\t\t\t\tto backend nodes. Forward proxies act as dedicated egress gateways for outbound IP whitelisting.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Framework Adapter Topologies:</strong> Deploying universal SvelteKit and Nuxt Nitro applications\n\t\t\t\twith zero application code changes.\n\t\t\t</li>\n\t\t</ul>',
	'compliance/eu-regulations':
		'<h3>EU Data Regulations & Compliance Engineering</h3>\n<p class="text-base sm:text-lg">\n  Building compliant applications for the European Union requires technical guarantees baked directly into the system architecture, from data ingestion to storage and automated subject requests.\n</p>\n<ul>\n  <li>\n    <strong>Automated GDPR Subject Requests (DSAR):</strong> Programmatically fulfill Right to Access (Art. 15), Right to Erasure (Art. 17), and Right to Data Portability (Art. 20) with automated multi-database cleanup webhooks and immutable cryptographic audit logs.\n  </li>\n  <li>\n    <strong>ePrivacy & Zero-Cookie Architecture:</strong> Differentiate strictly necessary operational storage (sessions, theme preferences) from consent-gated telemetry without using deceptive dark patterns.\n  </li>\n  <li>\n    <strong>Digital Markets Act (DMA) & Digital Services Act (DSA):</strong> Ensure open data interoperability, standardized export schemas, and transparent algorithmic recommendation disclosures.\n  </li>\n  <li>\n    <strong>EU AI Act Article 50 Content Provenance:</strong> Machine-readable disclosure headers and watermarking flags for synthetically generated text, images, and audio.\n  </li>\n  <li>\n    <strong>Sovereign Cloud Data Residency:</strong> Route sensitive European personal data exclusively to EU-based data centers (e.g. Frankfurt, Paris) in compliance with Schrems II and cross-border transfer frameworks.\n  </li>\n</ul>',
	'ecmascript/binary-streams':
		'<h3>Binary Streams, Buffers & Container Layouts</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tNative binary buffer transformations eliminate client-side polyfills for cryptography, file\n\t\t\tprocessing, and network serialisation.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong><code>Uint8Array.prototype.toBase64()</code>:</strong> Browser-native, specification-grade\n\t\t\t\tBase64 conversion without string corruption or memory overhead.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong><code>Uint8Array.prototype.toHex()</code>:</strong> Fast hexadecimal serialisation for\n\t\t\t\thashes, tokens, and cryptographic signatures.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong><code>Array.fromAsync()</code>:</strong> Consumes asynchronous iterables, ReadableStreams,\n\t\t\t\tand Promise batches directly into an array in a single operation.\n\t\t\t</li>\n\t\t</ul>',
	'ecmascript/discrete-transitions':
		'<h3>Discrete Transitions & DOM Interactivity</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tCSS discrete transitions and HTML5 background isolation provide butter-smooth entrance\n\t\t\tanimations without heavy JavaScript animation runtimes.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong><code>@starting-style</code> & <code>allow-discrete</code>:</strong> Transition CSS\n\t\t\t\tproperties directly from <code>display: none</code> to visible block layout.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong><code>inert</code> Attribute:</strong> Completely removes background DOM subtrees from\n\t\t\t\tfocus, selection, and accessibility trees when overlays are open.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Hardware Transforms:</strong> GPU-composited 3D spatial matrix operations calculated smoothly\n\t\t\t\twith zero layout thrashing.\n\t\t\t</li>\n\t\t</ul>',
	'ecmascript/math-and-maps':
		'<h3>Precision Math, Maps & Modern Iterators</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tES2026 introduces native mathematical accuracy algorithms and collection ergonomics directly\n\t\t\tinto standard ECMAScript.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong><code>Math.sumPrecise()</code>:</strong> Native IEEE-754 exact accumulator avoiding binary\n\t\t\t\tfloating-point roundoff errors without external BigNumber overhead.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong><code>Map.prototype.getOrInsert()</code>:</strong> Eliminates lookup-and-fallback boilerplate\n\t\t\t\tlogic by atomically inserting default values in a single call.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Iterator Helpers:</strong> Compose lazy, unallocated data transformation pipelines\n\t\t\t\tusing <code>.map()</code>, <code>.filter()</code>, <code>.take()</code>, and\n\t\t\t\t<code>.drop()</code> directly on standard Iterators.\n\t\t\t</li>\n\t\t</ul>',
	'ecmascript/resource-scopes':
		'<h3>Resource Scopes & Explicit Management</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tExplicit Resource Management (ERM) with <code>using</code> statements and decoupled promise resolvers\n\t\t\tstreamline asynchronous lifecycle management.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong><code>using (Symbol.dispose)</code>:</strong> Guarantees deterministic teardown for database\n\t\t\t\tconnections, mutex locks, and file handles upon block scope exit.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong><code>Promise.withResolvers()</code>:</strong> Exposes direct <code>resolve</code>\n\t\t\t\tand <code>reject</code> handles without nesting logic inside closure callbacks.\n\t\t\t</li>\n\t\t</ul>',
	'foundations/html5':
		'<h3>Modern HTML5 Semantics & Web Standards</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tWeb Standards provide native browser-level primitives that replace megabytes of legacy\n\t\t\tJavaScript libraries.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Native <code>&lt;dialog&gt;</code>:</strong> Provides automatic focus trapping,\n\t\t\t\tbackdrop dimming via <code>::backdrop</code>, and light dismissal with Esc without external\n\t\t\t\tdependencies.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Exclusive <code>&lt;details name="..."&gt;</code>:</strong> Groups accordion items\n\t\t\t\tnatively. Opening one item automatically closes siblings sharing the same <code>name</code> attribute.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Web Standards (Streams & Web Crypto):</strong> First-class browser APIs like\n\t\t\t\t<code>URLPattern</code>, <code>TransformStream</code>, and <code>crypto.subtle</code> execute\n\t\t\t\tat native C++ speeds.\n\t\t\t</li>\n\t\t</ul>',
	'foundations/icons-favicons':
		'<h3>Modern Icon & Favicon Systems</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tModern web standards eliminate large icon sprite libraries by leveraging responsive SVG\n\t\t\tfavicons and CSS mask icons.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Theme-Aware SVG Favicons:</strong> SVG favicons support embedded\n\t\t\t\t<code>&lt;style&gt;</code>\n\t\t\t\ttags and <code>@media (prefers-color-scheme: dark)</code>, dynamically switching colors\n\t\t\t\twithout JavaScript.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>CSS Mask Icons:</strong> By rendering a single <code>&lt;span&gt;</code> with\n\t\t\t\t<code>mask: url(...)</code>, icons inherit CSS <code>background-color</code> and\n\t\t\t\t<code>currentColor</code> while keeping the DOM tree flat.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>PWA Manifest & Apple Touch Icons:</strong> Configure\n\t\t\t\t<code>manifest.webmanifest</code>\n\t\t\t\tand <code>apple-touch-icon.png</code> for seamless cross-device home screen installation.\n\t\t\t</li>\n\t\t</ul>',
	'foundations/pnpm-ci':
		'<h3>PNPM Workspaces & CI/CD Pipelines</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tPNPM workspaces combined with GitHub Actions provide deterministic, lightning-fast dependency\n\t\t\tresolution and CI quality gates.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>The <code>catalog:</code> Protocol:</strong> Centralises dependency versioning in\n\t\t\t\t<code>pnpm-workspace.yaml</code>, preventing version mismatches across multiple packages in\n\t\t\t\ta monorepo.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Strict Frozen Lockfiles:</strong> Enforce\n\t\t\t\t<code>pnpm install --frozen-lockfile</code> in CI to guarantee that local build environments match\n\t\t\t\tautomated deployment servers bit-for-bit.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Matrix CI Testing:</strong> Execute automated type checking, linting, unit testing, and\n\t\t\t\tstatic builds concurrently across multiple Node versions and OS platforms.\n\t\t\t</li>\n\t\t</ul>',
	'foundations/styling-assets':
		'<h3>Tailwind CSS v4 & Modern Asset Pipelines</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tTailwind CSS v4 introduces a CSS-first architecture that eliminates <code\n\t\t\t\t>tailwind.config.js</code\n\t\t\t>\n\t\t\tin favor of native <code>@theme</code> blocks, cascade layers, and container queries.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>CSS-First <code>@theme</code>:</strong> Tokens bind directly to native CSS custom properties\n\t\t\t\twithout JavaScript runtime compilation overhead.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Modular Container Queries (<code>@container</code>):</strong> Components adapt based on\n\t\t\t\ttheir parent container width rather than the global viewport width.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Asset Optimisation & Immutable Delivery:</strong> Modern bundlers hash static assets\n\t\t\t\tand serve them with <code>Cache-Control: public, max-age=31536000, immutable</code>.\n\t\t\t</li>\n\t\t</ul>',
	'foundations/typescript':
		'<h3>TypeScript 6 & Modern Strict Typing</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tTypeScript 6 provides sound type inference, const type parameters, the <code>satisfies</code> operator,\n\t\t\tand strict discriminated unions.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>The <code>satisfies</code> Operator:</strong> Enforces that an expression matches an interface\n\t\t\t\twithout widening literal string or numeric types to general primitives.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Const Type Parameters:</strong> Allows generic functions to infer literal tuple and\n\t\t\t\tobject types automatically at the call site without requiring <code>as const</code>.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Discriminated Unions & Exhaustiveness:</strong> Guarantees that all variants of an event\n\t\t\t\tor state machine are handled safely at compile time.\n\t\t\t</li>\n\t\t</ul>',
	'infra/better-auth':
		'<h3>Modern Authentication, Passkeys & Better Auth</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tBetter Auth provides a comprehensive TypeScript authentication runtime with passwordless\n\t\t\tWebAuthn passkeys, HttpOnly cookie rotation, and organisation multi-tenancy.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Passkeys (WebAuthn):</strong> Asymmetric public-private keypairs anchored in hardware\n\t\t\t\tsecure enclaves (TouchID, FaceID, Windows Hello) that are immune to phishing.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>HttpOnly Session Cookies:</strong> Completely isolated from client JavaScript (<code\n\t\t\t\t\t>document.cookie</code\n\t\t\t\t>), protecting session tokens against XSS exfiltration.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Schema Ownership:</strong> Better Auth creates native Drizzle tables in your own database\n\t\t\t\twithout third-party auth vendor lock-in.\n\t\t\t</li>\n\t\t</ul>',
	'infra/databases-orm':
		'<h3>Modern Database Engines & Drizzle ORM</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tSelecting the right database engine and transport protocol determines application latency,\n\t\t\tedge compatibility, concurrency limits, and operational complexity.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Neon Serverless Postgres:</strong> Separates compute from storage, scaling compute to\n\t\t\t\tzero when idle and executing queries over sub-millisecond HTTP/WebSocket connections to solve\n\t\t\t\tserverless lambda connection starvation.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Turso & libSQL:</strong> Distributed SQLite for global edge deployments powered by libSQL.\n\t\t\t\tFeatures embedded local file replicas that execute reads directly from local in-memory/file storage\n\t\t\t\twith zero network hops.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>postgres.js:</strong> The fastest full-featured PostgreSQL client for Node.js, Bun, and\n\t\t\t\tDeno. Features zero dependencies, tagged-template literal queries, and native type serialisation.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>SQLite & better-sqlite3:</strong> The world\'s most widely deployed database engine. In-process,\n\t\t\t\tzero-configuration with Write-Ahead Logging (WAL) concurrency, ideal for local development, embedded\n\t\t\t\tsoftware, and single-container deployments.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>PostgreSQL (Stateful):</strong> The industry-standard ACID relational database with rich\n\t\t\t\tJSONB indexing, pgvector similarity search, and advanced transactional guarantees.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Drizzle ORM:</strong> Zero-runtime TypeScript SQL query builder that maps type-safe schemas\n\t\t\t\tdirectly to SQL dialects without heavy query translation overhead.\n\t\t\t</li>\n\t\t</ul>',
	'infra/redis-ratelimit':
		'<h3>Edge Caching & Sliding Window Rate Limiting</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tSliding window algorithms in Upstash Redis over stateless HTTP prevent traffic burst exploits\n\t\t\tacross fixed window intervals and defend against DDoS attacks.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>The Fixed Window Burst Vulnerability:</strong> In fixed window rate limiting, a client\n\t\t\t\tcan send its full limit at second 9 and another batch at second 10, executing a 2x burst across\n\t\t\t\tthe boundary.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Sliding Window Smoothness:</strong> Tracks a continuous rolling weighted window in Redis\n\t\t\t\tmemory, ensuring the client never exceeds quota across any arbitrary slice of time.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Stateless HTTP Redis:</strong> Upstash uses standard HTTPS requests instead of persistent\n\t\t\t\tTCP sockets, eliminating connection exhaustion on Cloudflare Workers and serverless edges.\n\t\t\t</li>\n\t\t</ul>',
	'infra/storage-s3-r2':
		'<h3>Object Storage: S3 Client, Cloudflare R2 & Presigned Uploads</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tModern file architectures decouple binary storage from application compute. Instead of routing\n\t\t\tgigabytes of user file uploads through web servers, clients stream data directly to object\n\t\t\tstorage buckets using short-lived presigned URLs.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>AWS SDK v3 (<code>@aws-sdk/client-s3</code>):</strong> Tree-shakable, modular client architecture\n\t\t\t\ttailored for edge runtimes and serverless functions.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Presigned Upload URLs:</strong> The application server cryptographically signs a PUT command;\n\t\t\t\tthe browser uploads directly to S3/R2 with zero server CPU or bandwidth overhead.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Cloudflare R2 (Zero Egress):</strong> 100% S3-compatible API with zero data transfer egress\n\t\t\t\tfees, drastically cutting bandwidth expenses for media-heavy web applications.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Multipart Streaming:</strong> Efficient chunking for multi-gigabyte video or archive files\n\t\t\t\twith parallel chunk verification and resumption.\n\t\t\t</li>\n\t\t</ul>',
	'operations/dev-environments':
		'<h3>Developer Workstations: Windows 11 WSL2 vs Fedora 44, VS Code vs VSCodium & Node 26</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tEngineering velocity depends heavily on workstation architecture: local filesystem I/O,\n\t\t\tcontainer virtualisation layers, telemetry isolation, and modern runtime tooling.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Windows 11 WSL2 vs Native Fedora 44:</strong> While WSL2 offers near-native\n\t\t\t\tperformance inside Linux virtual disks, cross-boundary access to Windows paths (<code\n\t\t\t\t\t>/mnt/c</code\n\t\t\t\t>) incurs severe 9P translation penalties. Fedora 44 provides 100% bare-metal NVMe and\n\t\t\t\tcontainer throughput.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>VS Code WSL vs VSCodium:</strong> VS Code uses a proprietary Microsoft server bridge to\n\t\t\t\trun inside WSL2. VSCodium provides a 100% open-source, telemetry-free binary configured with the\n\t\t\t\tOpen VSX Registry.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Node.js 26 & pnpm v12:</strong> Future-proof runtimes featuring native TypeScript execution\n\t\t\t\twithout external build steps and deterministic monorepo dependency deduplication.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>OpenRemote Integration:</strong> Open-source platform for orchestrating IoT assets, edge\n\t\t\t\tdevices, and real-time event telemetry in full-stack applications.\n\t\t\t</li>\n\t\t</ul>',
	'operations/seo-analytics':
		'<h3>SEO, Metadata & Privacy-First Web Analytics</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tOptimising discovery across search engine crawlers and social share cards while collecting\n\t\t\tprivacy-respecting, cookieless telemetry.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Structured SEO Meta:</strong> Configure Open Graph (OG), Twitter Card, and JSON-LD schema\n\t\t\t\ttags to maximise social preview click-through rates.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Privacy-Friendly Analytics (Plausible, Umami, Cloudflare Web Analytics):</strong> Track\n\t\t\t\tcore traffic metrics without intrusive cookie consent banners or GDPR tracking violations.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Core Web Vitals Telemetry:</strong> Monitor Largest Contentful Paint (LCP), Interaction\n\t\t\t\tto Next Paint (INP), and Cumulative Layout Shift (CLS) directly via navigator.sendBeacon.\n\t\t\t</li>\n\t\t</ul>',
	'operations/testing':
		'<h3>Modern Testing Architecture: Vitest & Playwright</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tA comprehensive testing pyramid combines instantaneous unit testing with Vitest, accessible\n\t\t\tcomponent testing, and deterministic end-to-end browser automation with Playwright.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Vitest:</strong> Native Vite-powered test runner sharing the exact same plugins, TypeScript\n\t\t\t\tconfigurations, and transforms with zero config duplication.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Component Testing:</strong> Renders real Svelte 5 Runes components in JSDOM / Happy-DOM\n\t\t\t\tto assert accessibility roles, keyboard interactions, and event emissions.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Playwright E2E:</strong> Drives real Chromium, Firefox, and WebKit browsers in headless\n\t\t\t\tmode to validate user flows and view transitions.\n\t\t\t</li>\n\t\t</ul>',
	'rendering/csp-transitions':
		'<h3>Security: Strict CSP, Nonces & View Transitions</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tSecuring web applications against Cross-Site Scripting (XSS) and clickjacking with strict\n\t\t\tContent Security Policies while providing fluid navigational animations with the View\n\t\t\tTransitions API.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Cryptographic CSP Nonces:</strong> Server-generated nonces ensure that only vetted scripts\n\t\t\t\texecuted by the framework can run, blocking malicious injected payloads.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Clickjacking Mitigation (<code>frame-ancestors \'none\'</code>):</strong> Prevents unauthorized\n\t\t\t\tembedding inside foreign iframes.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>View Transitions API:</strong> Natively morphs DOM elements between pages and route navigations\n\t\t\t\twithout complex layout calculations.\n\t\t\t</li>\n\t\t</ul>',
	'rendering/hydration-serialization':
		'<h3>Hydration Engines & Data Serialisation</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tPassing state across the server-to-client boundary requires specialised serialisers like <code\n\t\t\t\t>devalue</code\n\t\t\t>\n\t\t\tor <code>SuperJSON</code> that preserve complex JavaScript data structures.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Standard JSON Limitations:</strong> <code>JSON.stringify</code> converts\n\t\t\t\t<code>Date</code>\n\t\t\t\tobjects to strings, loses <code>Set</code> / <code>Map</code> prototypes, and throws on\n\t\t\t\t<code>BigInt</code>.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong><code>devalue</code> Engine:</strong> Powers SvelteKit and Nuxt payload transfers by serialising\n\t\t\t\tcircular references, custom prototypes, and native ECMAScript data structures safely.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Hydration Mismatch Prevention:</strong> Guarantees identical client state recreation on\n\t\t\t\tthe initial load without re-triggering network fetches.\n\t\t\t</li>\n\t\t</ul>',
	'rendering/strategies':
		'<h3>Rendering Strategies: SSG, SSR, Hybrid & CSR</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tSelecting the appropriate rendering model balances Time to First Byte (TTFB), First Contentful\n\t\t\tPaint (FCP), SEO indexability, and cloud infrastructure expenditure.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>SSG (Static Site Generation):</strong> Pre-renders HTML at build time for instant CDN\n\t\t\t\tdelivery and zero server compute overhead.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>SSR (Server-Side Rendering):</strong> Renders fresh dynamic HTML on every request for\n\t\t\t\tpersonalized, real-time data.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Hybrid / ISR:</strong> Combines static caching with background regeneration triggers.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>CSR (Client-Side Rendering):</strong> Offloads rendering entirely to the browser for thick,\n\t\t\t\toffline-capable applications.\n\t\t\t</li>\n\t\t</ul>',
	'runtimes/engines':
		'<h3>Modern JavaScript Runtimes: Node.js 24, Bun & Deno 2</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tThe JavaScript runtime landscape in 2026 offers distinct trade-offs across execution engines,\n\t\t\tsecurity models, cold-start latency, and tooling integration.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Node.js 24 LTS:</strong> The industry standard runtime featuring native TypeScript execution\n\t\t\t\t(type stripping), built-in SQLite, and stable permission models.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Bun 1.2:</strong> An all-in-one toolkit powered by WebKit JavaScriptCore and Zig with\n\t\t\t\tinstant package installs, native bundler, and ultra-fast cold starts.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Deno 2.2:</strong> A secure-by-default runtime with granular CLI permissions, out-of-the-box\n\t\t\t\tnpm compatibility, and deep Web Standards compliance.\n\t\t\t</li>\n\t\t</ul>',
	'runtimes/nitro-hono':
		'<h3>Universal Server Engines: Nitro & Hono</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tModern full-stack architectures decouple web servers from rigid hosting environments using\n\t\t\tuniversal server runtimes like UnJS Nitro and lightweight frameworks like Hono.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>UnJS Nitro:</strong> The universal server engine powering Nuxt and standalone microservices\n\t\t\t\twith cross-runtime presets (Node, Cloudflare, Vercel, Netlify, Bun, Deno) and built-in storage\n\t\t\t\tdrivers (unstorage).\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Hono:</strong> A lightweight (&lt;15KB), ultra-fast web framework engineered for Web Standards,\n\t\t\t\tedge compute isolates, typed RPC contracts, and zero-overhead routing.\n\t\t\t</li>\n\t\t</ul>',
	'runtimes/project-structures':
		'<h3>Modern Project Types & Directory Structures</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tChoosing the right project topology is fundamental to long-term maintainability, code reuse,\n\t\t\tand team velocity.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>SvelteKit 2 Layout:</strong> Enforces strong server-side isolation with\n\t\t\t\t<code>$lib/server</code>\n\t\t\t\tand deterministic page routing with <code>+page.server.ts</code> and\n\t\t\t\t<code>hooks.server.ts</code>.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Nuxt 4 Structure:</strong> Centralises frontend components and composables in\n\t\t\t\t<code>app/</code>\n\t\t\t\twhile isolating backend endpoints in <code>server/api/</code>.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Monorepo Topologies:</strong> Organises large teams into decoupled\n\t\t\t\t<code>apps/</code>\n\t\t\t\tand reusable internal <code>packages/</code> linked via PNPM workspace catalogs.\n\t\t\t</li>\n\t\t</ul>',
	'runtimes/vite-packaging':
		'<h3>Vite 6 Architecture & Library Packaging</h3>\n\t\t<p class="text-base sm:text-lg">\n\t\t\tModern frontend libraries use modern packaging standards including conditional <code\n\t\t\t\t>exports</code\n\t\t\t>, TypeScript declaration bundling, and Vite 6\'s optimised build pipeline.\n\t\t</p>\n\t\t<ul>\n\t\t\t<li>\n\t\t\t\t<strong>Vite 6 & Rolldown:</strong> Delivers lightning-fast Hot Module Replacement (HMR) and optimised\n\t\t\t\tmulti-target build outputs.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong><code>svelte-package</code> & <code>unbuild</code>:</strong> Compiles Svelte runes\n\t\t\t\tcomponents, processes TypeScript definitions (<code>.d.ts</code>), and produces standard ESM\n\t\t\t\tartifacts.\n\t\t\t</li>\n\t\t\t<li>\n\t\t\t\t<strong>Conditional <code>package.json</code> <code>exports</code>:</strong> Enforces explicit\n\t\t\t\tpublic API boundaries, preventing consumers from importing internal unexported modules.\n\t\t\t</li>\n\t\t</ul>',
	'security/anonymity-oblivious':
		'<h3>Web Anonymity & Oblivious Protocol Architectures</h3>\n<p class="text-base sm:text-lg">\n  Decoupling network identities (IP addresses, TLS signatures) from application layer requests enables true privacy-preserving telemetry, anti-fraud verifications, and anonymous browsing.\n</p>\n<ul>\n  <li>\n    <strong>Oblivious HTTP (OHTTP / RFC 9458):</strong> Employs Hybrid Public Key Encryption (HPKE / RFC 9180) across an untrusted Relay and a Target Gateway. The Relay knows the client IP but cannot read the encrypted payload; the Gateway decrypts the payload but never knows the client IP.\n  </li>\n  <li>\n    <strong>Private State Tokens (PST / Privacy Pass RFC 9578):</strong> Uses blind signatures (VOPRF) to issue cryptographic tokens that prove a client passed anti-bot or subscriber checks without revealing identity across different domains.\n  </li>\n  <li>\n    <strong>Onion-Location & Hidden Services:</strong> Advertises authenticated Tor onion endpoints directly via HTTP response headers, allowing privacy-conscious clients to route traffic through 6-hop encrypted circuits.\n  </li>\n  <li>\n    <strong>Differential Privacy in Telemetry:</strong> Injects calibrated mathematical noise into aggregate metrics to guarantee individual user actions cannot be reconstructed.\n  </li>\n</ul>',
	'security/bots-crawlers-scraping':
		'<h3>Robots, AI Scrapers & Bot Defense Engineering</h3>\n<p class="text-base sm:text-lg">\n  The explosion of autonomous AI scrapers and LLM retrieval agents necessitates modern machine-readable content protocols, lawful copyright opt-outs, and zero-tracking bot mitigation.\n</p>\n<ul>\n  <li>\n    <strong>RFC 9309 Robots Exclusion Protocol & AI Governance:</strong> Declare deterministic crawl boundaries for major AI scrapers (<code>GPTBot</code>, <code>ClaudeBot</code>, <code>PerplexityBot</code>, <code>Bytespider</code>).\n  </li>\n  <li>\n    <strong><code>llms.txt</code> & <code>llms-full.txt</code> Standards:</strong> Provide curated, structured markdown feeds optimized for AI reasoning and contextual discovery without scraping heavy HTML.\n  </li>\n  <li>\n    <strong>EU TDM & <code>X-Robots-Tag: noai</code> Reservations:</strong> Enforce machine-readable Text and Data Mining reservations under EU Copyright Directive Article 4 (<code>&lt;meta name="tdm-reservation" content="1"&gt;</code>) to legally restrict automated model training.\n  </li>\n  <li>\n    <strong>TLS & Network Fingerprinting (JA3 / JA4):</strong> Analyze client TLS extension ordering and HTTP/2 <code>SETTINGS</code> frame characteristics at the WAF layer to detect headless scraper runtimes.\n  </li>\n  <li>\n    <strong>Zero-Tracking Proof-of-Work Challenges:</strong> Replace invasive, tracking-heavy CAPTCHAs with client-side cryptographic SHA-256 challenges (Altcha standard) that stop automated brute force attacks with zero user profiling.\n  </li>\n</ul>',
	'security/defensive-headers':
		"<h3>Modern Web Security & Defensive Architecture</h3>\n<p class=\"text-base sm:text-lg\">\n  Comprehensive browser-side defense-in-depth requires more than basic sanitization. Modern web architectures in 2026 rely on cryptographic nonces, execution boundaries, and hardware isolation headers to render entire classes of injection and timing attacks obsolete.\n</p>\n<ul>\n  <li>\n    <strong>Strict CSP Level 3 (<code>'strict-dynamic'</code>):</strong> Replaces fragile domain allowlists with per-request cryptographic nonces (<code>'nonce-UUID'</code>), ensuring dynamically loaded trusted dependencies execute while malicious inline scripts are immediately blocked.\n  </li>\n  <li>\n    <strong>Cross-Origin Isolation (COOP + COEP + CORP):</strong> Enables high-precision WebAssembly threads, <code>SharedArrayBuffer</code>, and prevents Spectre-style side-channel microarchitectural attacks by isolating browsing context groups.\n  </li>\n  <li>\n    <strong>Trusted Types API:</strong> Eliminates DOM-based XSS by requiring typed objects (<code>TrustedHTML</code>, <code>TrustedScript</code>) before strings can be written to dangerous injection sinks like <code>innerHTML</code>.\n  </li>\n  <li>\n    <strong>Fine-Grained Permissions-Policy:</strong> Explicitly disables unneeded device hardware access (cameras, microphones, sensors, FLoC/Topics tracking) at the HTTP protocol layer.\n  </li>\n</ul>",
	'security/privacy-fingerprinting':
		'<h3>Privacy Engineering & Anti-Fingerprinting Architecture</h3>\n<p class="text-base sm:text-lg">\n  As third-party cookies are deprecated, covert tracking vectors like device entropy fingerprinting, CNAME cloaking, and bounce tracking have become the primary threat to web privacy.\n</p>\n<ul>\n  <li>\n    <strong>Global Privacy Control (<code>Sec-GPC: 1</code>):</strong> Machine-readable HTTP header signaling the user\'s universal legal opt-out from personal data sale, sharing, and cross-site profiling.\n  </li>\n  <li>\n    <strong>Entropy Fingerprint Resistance:</strong> Introduces imperceptible micro-jitter to Canvas 2D, WebGL, and Web Audio rendering outputs to prevent deterministic device hashing while maintaining visual fidelity.\n  </li>\n  <li>\n    <strong>Storage Partitioning (CHIPS / Cookies Having Independent Partitioned State):</strong> Isolates cookie jars and local storage per top-level site context, eliminating cross-site tracking via embedded iframes.\n  </li>\n  <li>\n    <strong>Link Decoration & Bounce Tracking Defenses:</strong> Strips tracking query parameters (<code>utm_*</code>, <code>fbclid</code>, <code>gclid</code>) and prevents stateful cross-site redirects.\n  </li>\n</ul>'
};
